; border-radius: 999px; border: 1px solid var(--border-2); color: var(--text-2); padding: 2px 6px; }\n.savant-status { display: inline-flex; align-items: center; gap: 6px; }\n.savant-status .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--text-3); box-shadow: 0 0 0 2px var(--surface-0) inset; }\n.savant-status.ok .dot { background: var(--success-0); }\n.savant-status.warn .dot { background: var(--warn-0); }\n.savant-status.err .dot { background: var(--error-0); }\n\n/* Shell */\n.shell { background: var(--bg-1); color: var(--text-1); width: 100%; height: 100vh; display: flex; flex-direction: column; }\n.top-strip { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: var(--space-4); padding: calc(var(--space-4)*var(--density-y)) var(--space-5); background: var(--bg-2); border-bottom: 1px solid var(--border-1); }\n.palaver-layout { flex: 1; display: grid; grid-template-columns: 56px 1fr 360px; gap: var(--space-4); padding: var(--space-4); }\n.palaver-left { }\n.palaver-center { min-width: 0; display: grid; grid-template-rows: auto 1fr auto; gap: var(--space-4); }\n.palaver-right { }\n\n.primary-workspace { display: grid; grid-template-rows: 1fr auto; gap: var(--space-3); min-height: 0; }\n.message-list { overflow: auto; padding: var(--space-3); background: var(--surface-0); border: 1px solid var(--border-1); border-radius: var(--radius-1); }\n.message { padding: calc(var(--space-3)*var(--density-y)) var(--space-4); border-bottom: 1px dashed var(--border-1); position: relative; }\n.message:last-child { border-bottom: 0; }\n.message .meta { color: var(--text-3); font-size: 12px; margin-bottom: 4px; display: flex; gap: 10px; align-items: center; }\n.message .actions { position: absolute; right: var(--space-3); top: var(--space-3); display: none; gap: 6px; }\n.message:hover .actions, .message:focus-within .actions { display: flex; }\n.message .bubble { color: var(--text-0); }\n\n.composer { display: grid; grid-template-rows: auto auto; gap: var(--space-2); background: var(--surface-0); border: 1px solid var(--border-1); border-radius: var(--radius-1); padding: var(--space-3); }\n.capsules { display: flex; flex-wrap: wrap; gap: 6px; }\n.capsule { border: 1px solid var(--border-2); background: var(--surface-1); border-radius: 999px; padding: 4px 8px; font-size: 12px; color: var(--text-2); display: inline-flex; gap: 6px; align-items: center; }\n.capsule button { background: transparent; border: 0; color: var(--text-2); }\n.input-row { display: grid; grid-template-columns: 1fr auto; gap: var(--space-2); }\n.input-row textarea { width: 100%; resize: none; background: var(--bg-1); color: var(--text-1); border: 1px solid var(--border-2); border-radius: var(--radius-1); padding: var(--space-3); min-height: 56px; }\n.input-row .send { background: var(--accent-0); color: #08111f; border: 0; border-radius: var(--radius-1); padding: 10px 14px; box-shadow: var(--accent-raise); cursor: pointer; }\n.input-row .send:disabled { opacity: .5; cursor: not-allowed; }\n\n.rail { display: grid; grid-template-rows: auto auto 1fr; gap: var(--space-3); background: var(--surface-0); border: 1px solid var(--border-1); border-radius: var(--radius-1); padding: var(--space-3); height: 100%; }\n.rail .mark { width: 28px; height: 28px; display: grid; place-items: center; background: var(--bg-2); border: 1px solid var(--border-1); border-radius: 6px; font-weight: 700; color: var(--text-0); }\n.rail .command-trigger { background: transparent; color: var(--text-2); border: 1px dashed var(--border-2); border-radius: var(--radius-0); padding: 4px 6px; font-size: 12px; }\n.rail nav { display: grid; gap: 2px; }\n.rail-item { display: grid; grid-template-columns: 16px 1fr; align-items: center; gap: 8px; color: var(--text-2); background: transparent; border: 0; text-align: left; font-size: 12px; padding: 8px 6px; border-radius: 6px; cursor: pointer; }\n.rail-item:hover { background: var(--surface-2); }\n.rail-item.active { background: var(--surface-2); color: var(--text-0); box-shadow: inset 0 0 0 1px var(--border-2); }\n\n.context-panel { background: var(--surface-0); border: 1px solid var(--border-1); border-radius: var(--radius-1); padding: var(--space-3); height: 100%; }\n.context-row { display: flex; align-items: center; justify-content: space-between; border: 1px dashed var(--border-2); border-radius: var(--radius-0); padding: 6px 8px; color: var(--text-2); }\n.context-stack { display: grid; gap: 8px; margin-top: var(--space-3); }\n\n.activity-drawer { background: var(--surface-0); border-top: 1px solid var(--border-1); padding: var(--space-3); }\n.receipt { border: 1px solid var(--border-2); border-radius: var(--radius-0); padding: 8px 10px; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", \"Courier New\", monospace; font-size: 12px; color: var(--text-2); }\n\n.statusbar { display: flex; align-items: center; gap: var(--space-4); padding: 6px var(--space-4); border-top: 1px solid var(--border-1); background: var(--bg-2); font-size: 12px; color: var(--text-2); }\n.statusbar .spacer { flex: 1; }\n.statusbar .pill { border: 1px solid var(--border-2); border-radius: 999px; padding: 2px 8px; }\n\n/* Command palette */\n.command-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.35); display: grid; place-items: start center; padding-top: 10vh; z-index: 50; }\n.command-center { width: min(720px, 92vw); max-height: 70vh; background: var(--surface-1); color: var(--text-1); border: 1px solid var(--border-2); border-radius: var(--radius-2); box-shadow: var(--shadow-1); overflow: hidden; }\n.command-center [cmdk-input] { width: 100%; padding: 12px 14px; background: var(--bg-1); border: 0; color: var(--text-1); border-bottom: 1px solid var(--border-1); }\n.command-center [cmdk-list] { max-height: 50vh; overflow: auto; padding: 6px; }\n.command-center [cmdk-empty] { padding: 10px 12px; color: var(--text-3); }\n.command-center [cmdk-item] { padding: 8px 10px; border-radius: 6px; }\n.command-center [cmdk-item][data-selected=\"true\"] { background: var(--surface-2); }\n\n/* Responsive morphology */\n@media (max-width: 1100px) {\n  .palaver-layout { grid-template-columns: 48px 1fr; }\n  .palaver-right { display: none; }\n}\n@media (max-width: 700px) {\n  .palaver-layout { grid-template-columns: 1fr; padding: var(--space-2); }\n  .palaver-left { display: none; }\n  .top-strip { grid-template-columns: 1fr auto; }\n}\n"},"tool_name":"patch_file"}
