{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/main.jsx","contents":"import React from \"react\"\nimport ReactDOM from \"react-dom/client\"\nimport App from \"./App.tsx\"\nimport \"./palaver/styles/tokens.css\"\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n)\n"},"tool_name":"patch_file"}
