{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/state/ui-store.ts","contents":"import { create } from \"zustand\"\nimport { persist } from \"zustand/middleware\"\n\nexport type Density = \"comfortable\" | \"compact\"\n\nexport type Mode = \"default\" | \"development\" | \"focus\"\n\ntype UIState = {\n  density: Density\n  mode: Mode\n  showRight: boolean\n  showLeft: boolean\n  activityOpen: boolean\n  leftSize: number\n  rightSize: number\n  setDensity: (d: Density) => void\n  setMode: (m: Mode) => void\n  toggleActivity: () => void\n  setPanels: (v: Partial<Pick<UIState, \"showLeft\" | \"showRight\">>) => void\n  setSizes: (v: Partial<Pick<UIState, \"leftSize\" | \"rightSize\">>) => void\n}\n\nexport const useUIStore = create<UIState>()(\n  persist(\n    (set) => ({\n      density: \"comfortable\",\n      mode: \"default\",\n      showRight: true,\n      showLeft: true,\n      activityOpen: false,\n      leftSize: 56,\n      rightSize: 360,\n      setDensity: (density) => set({ density }),\n      setMode: (mode) => set({ mode }),\n      toggleActivity: () => set((s) => ({ activityOpen: !s.activityOpen })),\n      setPanels: (v) => set(v),\n      setSizes: (v) => set(v)\n    }),\n    { name: \"palaver-ui\" }\n  )\n)\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/state/conversation-store.ts","contents":"import { create } from \"zustand\"\n\nexport type Role = \"user\" | \"assistant\" | \"system\"\n\nexport type Receipt = {\n  operation: string\n  path?: string\n  expected_digest?: string\n  resulting_digest?: string\n  ok?: boolean\n  timestamp?: string\n}\n\nexport type Message = {\n  id: string\n  role: Role\n  text: string\n  answer?: string\n  response?: string\n  trace?: any\n  receipts?: Receipt[]\n  ts: number\n}\n\ntype State = {\n  messages: Message[]\n  selectedId?: string\n  pending: boolean\n  error?: string\n  attach: { type: string; label: string; data: any }[]\n  add: (m: Message) => void\n  setPending: (v: boolean) => void\n  setError: (e?: string) => void\n  select: (id?: string) => void\n  addAttach: (a: { type: string; label: string; data: any }) => void\n  removeAttach: (label: string) => void\n  clearAttach: () => void\n}\n\nexport const useConversation = create<State>((set) => ({\n  messages: [],\n  pending: false,\n  attach: [],\n  add: (m) => set((s) => ({ messages: [...s.messages, m] })),\n  setPending: (pending) => set({ pending }),\n  setError: (error) => set({ error }),\n  select: (selectedId) => set({ selectedId }),\n  addAttach: (a) => set((s) => ({ attach: [...s.attach, a] })),\n  removeAttach: (label) => set((s) => ({ attach: s.attach.filter((x) => x.label !== label) })),\n  clearAttach: () => set({ attach: [] })\n}))\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/services/api.ts","contents":"export type ChatResult = {\n  response?: string\n  answer?: string\n  trace?: any\n}\n\nasync function http<T>(path: string, init?: RequestInit): Promise<T> {\n  const res = await fetch(path, init)\n  if (!res.ok) {\n    const text = await res.text().catch(() => \"\")\n    throw new Error(`${res.status} ${res.statusText}${text ? ` — ${text}` : \"\"}`)\n  }\n  return res.json() as Promise<T>\n}\n\nexport async function health() {\n  return http<{ ok: boolean; time?: string }>(\"/api/health\")\n}\n\nexport async function chat(message: string) {\n  return http<ChatResult>(\"/api/chat\", {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ message })\n  })\n}\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/components/StatusBar.tsx","contents":"import { useEffect, useState } from \"react\"\nimport { health } from \"../services/api\"\nimport { useUIStore } from \"../state/ui-store\"\n\nexport default function StatusBar() {\n  const { density, mode, toggleActivity } = useUIStore()\n  const [ok, setOk] = useState<boolean | null>(null)\n\n  useEffect(() => {\n    let alive = true\n    const poll = async () => {\n      try {\n        const res = await health()\n        if (!alive) return\n        setOk(!!res.ok)\n      } catch (_) {\n        if (!alive) return\n        setOk(false)\n      }\n    }\n    poll()\n    const id = setInterval(poll, 5000)\n    return () => { alive = false; clearInterval(id) }\n  }, [])\n\n  return (\n    <div className=\"statusbar\" role=\"status\" aria-live=\"polite\">\n      <span className={`savant-status ${ok == null ? \"\" : ok ? \"ok\" : \"err\"}`}>\n        <span className=\"dot\" aria-hidden />\n        {ok == null ? \"checking\" : ok ? \"connected\" : \"offline\"}\n      </span>\n      <span className=\"pill\" title=\"Density\">{density}</span>\n      <span className=\"pill\" title=\"Mode\">{mode}</span>\n      <span className=\"spacer\" />\n      <button className=\"pill\" onClick={toggleActivity} aria-label=\"Toggle activity drawer\">activity</button>\n    </div>\n  )\n}\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/components/Tooltip.tsx","contents":"import { ReactNode, useId, useState } from \"react\"\n\nexport default function Tooltip({ label, children }: { label: string; children: ReactNode }) {\n  const id = useId()\n  const [open, setOpen] = useState(false)\n  return (\n    <span className=\"tooltip-wrap\" onMouseEnter={() => setOpen(true)} onMouseLeave={() => setOpen(false)}>\n      <span aria-describedby={id}>{children}</span>\n      {open && (\n        <span role=\"tooltip\" id={id} className=\"tooltip\" style={{ position: \"absolute\", transform: \"translateY(-110%)\", background: \"#0b0d10\", color: \"#c9d1d9\", border: \"1px solid #263042\", borderRadius: 6, padding: \"4px 8px\", fontSize: 12 }}>\n          {label}\n        </span>\n      )}\n    </span>\n  )\n}\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/components/ActivityDrawer.tsx","contents":"import { useConversation } from \"../state/conversation-store\"\n\nexport default function ActivityDrawer() {\n  const { messages } = useConversation()\n  const receipts = messages.flatMap((m) => m.receipts || [])\n  if (!receipts.length) return (\n    <div className=\"activity-drawer\">\n      <div className=\"savant-badge\">no recent receipts</div>\n    </div>\n  )\n\n  return (\n    <div className=\"activity-drawer\">\n      <div className=\"receipts\">\n        {receipts.slice(-10).map((r, i) => (\n          <div className=\"receipt\" key={i}>\n            <div><strong>operation</strong>: {r.operation}</div>\n            {r.path && <div><strong>path</strong>: {r.path}</div>}\n            {r.expected_digest && <div><strong>expected</strong>: {r.expected_digest}</div>}\n            {r.resulting_digest && <div><strong>result</strong>: {r.resulting_digest}</div>}\n            {typeof r.ok === \"boolean\" && <div><strong>ok</strong>: {String(r.ok)}</div>}\n            {r.timestamp && <div><strong>time</strong>: {r.timestamp}</div>}\n          </div>\n        ))}\n      </div>\n    </div>\n  )\n}\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/components/MessageList.tsx","contents":"import { useEffect, useRef } from \"react\"\nimport { useConversation } from \"../state/conversation-store\"\n\nfunction useScrollAnchor(dep: any) {\n  const ref = useRef<HTMLDivElement>(null)\n  const pinnedRef = useRef(true)\n  useEffect(() => {\n    const list = ref.current\n    if (!list) return\n    const onScroll = () => {\n      const atBottom = list.scrollHeight - list.scrollTop - list.clientHeight < 32\n      pinnedRef.current = atBottom\n    }\n    list.addEventListener(\"scroll\", onScroll)\n    return () => list.removeEventListener(\"scroll\", onScroll)\n  }, [])\n\n  useEffect(() => {\n    const list = ref.current\n    if (!list) return\n    if (pinnedRef.current) {\n      list.scrollTop = list.scrollHeight\n    }\n  }, [dep])\n\n  return ref\n}\n\nexport default function MessageList() {\n  const { messages, select, selectedId, addAttach } = useConversation()\n  const ref = useScrollAnchor(messages.length)\n\n  return (\n    <div className=\"message-list\" ref={ref}>\n      {messages.length === 0 && (\n        <div className=\"savant-empty\">No conversation yet. Send a message to begin.</div>\n      )}\n      {messages.map((m) => (\n        <article key={m.id} className=\"message\" onClick={() => select(m.id)} aria-selected={selectedId === m.id}>\n          <div className=\"meta\">\n            <span className=\"savant-badge\">{m.role}</span>\n            {m.trace?.provider && <span className=\"savant-badge\" title=\"Execution lineage\">{m.trace.provider}</span>}\n            {m.trace?.model && <span className=\"savant-badge\">{m.trace.model}</span>}\n          </div>\n          <div className=\"actions\" aria-label=\"message actions\">\n            <button onClick={() => navigator.clipboard.writeText(m.text)} aria-label=\"Copy message\">copy</button>\n            <button onClick={() => addAttach({ type: \"quote\", label: `quote:${m.id}`, data: m.text })} aria-label=\"Quote to composer\">quote</button>\n            <button onClick={() => {/* pin placeholder UI only */}} aria-label=\"Pin message\">pin</button>\n          </div>\n          <div className=\"bubble\">\n            <div>{m.text}</div>\n            {m.response && m.response !== m.text && (\n              <div style={{ marginTop: 8, color: \"#c9d1d9\" }}>{m.response}</div>\n            )}\n          </div>\n        </article>\n      ))}\n    </div>\n  )\n}\n","tool_name":"patch_file"}
{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/components/Composer.tsx","contents":"import { FormEvent, useEffect, useRef, useState } from \"react\"\nimport { chat } from \"../services/api\"\nimport { useConversation } from \"../state/conversation-store\"\n\nexport default function Composer() {\n  const { add, pending, setPending, setError, attach, removeAttach, clearAttach } = useConversation()\n  const [value, setValue] = useState(\"\")\n  const taRef = useRef<HTMLTextAreaElement>(null)\n\n  function resize() {\n    const el = taRef.current\n    if (!el) return\n    el.style.height = \"auto\"\n    el.style.height = Math.min(240, Math.max(56, el.scrollHeight)) + \"px\"\n  }\n\n  useEffect(() => { resize() }, [value])\n\n  const onSubmit = async (e: FormEvent) => {\n    e.preventDefault()\n    const message = value.trim()\n    if (!message) return\n\n    const id = crypto.randomUUID()\n    add({ id, role: \"user\", text: message, ts: Date.now() })\n    setValue(\"\")\n    setPending(true)\n    setError(undefined)\n\n    try {\n      const res = await chat(message)\n      const response = res.response ?? res.answer ?? \"\"\n      const receipts = Array.isArray(res.trace?.receipts) ? res.trace?.receipts : []\n      add({ id: crypto.randomUUID(), role: \"assistant\", text: response, response, answer: res.answer, trace: res.trace, receipts, ts: Date.now() })\n    } catch (err: any) {\n      setError(String(err?.message || err))\n      add({ id: crypto.randomUUID(), role: \"system\", text: String(err?.message || err), ts: Date.now() })\n    } finally {\n      setPending(false)\n      clearAttach()\n    }\n  }\n\n  return (\n    <form className=\"composer\" onSubmit={onSubmit}>\n      <div className=\"capsules\" aria-live=\"polite\">\n        {attach.map((a) => (\n          <span className=\"capsule\" key={a.label} title={`source: ${a.type}`}>\n            {a.label}\n            <button type=\"button\" onClick={() => removeAttach(a.label)} aria-label={`Remove ${a.label}`}>×</button>\n          </span>\n        ))}\n      </div>\n      <div className=\"input-row\">\n        <textarea\n          ref={taRef}\n          value={value}\n          onChange={(e) => setValue(e.target.value)}\n          onKeyDown={(e) => {\n            if ((e.metaKey || e.ctrlKey) && e.key === \"Enter\") {\n              e.preventDefault(); (e.currentTarget.form as HTMLFormElement | null)?.requestSubmit()\n            }\n            if (e.key === \"/\" && value.length === 0) {\n              // show lightweight slash help text in placeholder behavior\n            }\n          }}\n          placeholder=\"Message Palaver… (/ for commands)\"\n          aria-label=\"Message composer\"\n        />\n        <button className=\"send\" disabled={pending} aria-disabled={pending} aria-busy={pending}>\n          {pending ? \"Sending…\" : \"Send\"}\n        </button>\n      </div>\n    </form>\n  )\n}\n","tool_name":"patch_file"}
