{"path":"ontology/obelisks/_template/segue/gates/_template/segue/innates/_template/segue/exiles/palaver/apps/webui-nextgen/src/palaver/workspace/CognitiveShell.tsx","contents":"import { useEffect } from \"react\"\n\nimport AmbientEnvironment from \"../environment/AmbientEnvironment\"\nimport CommandCenter from \"../components/CommandCenter\"\nimport ContextPanel from \"../components/ContextPanel\"\nimport ObservatoryRail from \"../components/ObservatoryRail\"\nimport { ObservatoryRouter } from \"../observatories\"\nimport { useWorkspaceStore } from \"../state/workspace-store\"\nimport StatusBar from \"../components/StatusBar\"\nimport Composer from \"../components/Composer\"\nimport MessageList from \"../components/MessageList\"\nimport ActivityDrawer from \"../components/ActivityDrawer\"\nimport { useUIStore } from \"../state/ui-store\"\n\nexport default function CognitiveShell() {\n  const { active, setCommandOpen } = useWorkspaceStore()\n  const { mode, setMode, density, setDensity, activityOpen } = useUIStore()\n\n  useEffect(() => {\n    const handler = (event: KeyboardEvent) => {\n      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === \"k\") {\n        event.preventDefault(); setCommandOpen(true)\n      }\n      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === \"b\") {\n        event.preventDefault(); setMode(mode === \"focus\" ? \"default\" : \"focus\")\n      }\n      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === \";\") {\n        event.preventDefault(); setDensity(density === \"compact\" ? \"comfortable\" : \"compact\")\n      }\n    }\n    window.addEventListener(\"keydown\", handler)\n    return () => window.removeEventListener(\"keydown\", handler)\n  }, [setCommandOpen, mode, setMode, density, setDensity])\n\n  useEffect(() => {\n    document.documentElement.setAttribute(\"data-density\", density)\n  }, [density])\n\n  return (\n    <main className=\"shell\">\n      <AmbientEnvironment />\n    