import { create } from "zustand"
import { persist } from "zustand/middleware"

export type Density = "comfortable" | "compact"

export type Mode = "default" | "development" | "focus"

type UIState = {
  density: Density
  mode: Mode
  showRight: boolean
  showLeft: boolean
  activityOpen: boolean
  leftSize: number
  rightSize: number
  setDensity: (d: Density) => void
  setMode: (m: Mode) => void
  toggleActivity: () => void
  setPanels: (v: Partial<Pick<UIState, "showLeft" | "showRight">>) => void
  setSizes: (v: Partial<Pick<UIState, "leftSize" | "rightSize">>) => void
}

export const useUIStore = create<UIState>()(
  persist(
    (set) => ({
      density: "comfortable",
      mode: "default",
      showRight: true,
      showLeft: true,
      activityOpen: false,
      leftSize: 56,
      rightSize: 360,
      setDensity: (density) => set({ density }),
      setMode: (mode) => set({ mode }),
      toggleActivity: () => set((s) => ({ activityOpen: !s.activityOpen })),
      setPanels: (v) => set(v),
      setSizes: (v) => set(v)
    }),
    { name: "palaver-ui" }
  )
)

