import { FormEvent, useEffect, useRef, useState } from "react"
import { chat } from "../services/api"
import { useConversation } from "../state/conversation-store"

export default function Composer() {
  const { add, pending, setPending, setError, attach, removeAttach, clearAttach } = useConversation()
  const [value, setValue] = useState("")
  const taRef = useRef<HTMLTextAreaElement>(null)

  function resize() {
    const el = taRef.current
    if (!el) return
    el.style.height = "auto"
    el.style.height = Math.min(240, Math.max(56, el.scrollHeight)) + "px"
  }

  useEffect(() => { resize() }, [value])

  const onSubmit = async (e: FormEvent) => {
    e.preventDefault()
    const message = value.trim()
    if (!message) return

    const id = crypto.randomUUID()
    add({ id, role: "user", text: message, ts: Date.now() })
    setValue("")
    setPending(true)
    setError(undefined)

    try {
      const res = await chat(message)
      const response = res.response ?? res.answer ?? ""
      const receipts = Array.isArray(res.trace?.receipts) ? res.trace?.receipts : []
      add({ id: crypto.randomUUID(), role: "assistant", text: response, response, answer: res.answer, trace: res.trace, receipts, ts: Date.now() })
    } catch (err: any) {
      setError(String(err?.message || err))
      add({ id: crypto.randomUUID(), role: "system", text: String(err?.message || err), ts: Date.now() })
    } finally {
      setPending(false)
      clearAttach()
    }
  }

  return (
    <form className="composer" onSubmit={onSubmit}>
      <div className="capsules" aria-live="polite">
        {attach.map((a) => (
          <span className="capsule" key={a.label} title={`source: ${a.type}`}>
            {a.label}
            <button type="button" onClick={() => removeAttach(a.label)} aria-label={`Remove ${a.label}`}>×</button>
          </span>
        ))}
      </div>
      <div className="input-row">
        <textarea
          ref={taRef}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={(e) => {
            if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
              e.preventDefault(); (e.currentTarget.form as HTMLFormElement | null)?.requestSubmit()
            }
            if (e.key === "/" && value.length === 0) {
              // show lightweight slash help text in placeholder behavior
            }
          }}
          placeholder="Message Palaver… (/ for commands)"
          aria-label="Message composer"
        />
        <button className="send" disabled={pending} aria-disabled={pending} aria-busy={pending}>
          {pending ? "Sending…" : "Send"}
        </button>
      </div>
    </form>
  )
}

