import { Command } from "cmdk"
import { useEffect, useMemo, useState } from "react"
import {
  Observatory,
  useWorkspaceStore
} from "../state/workspace-store"
import { useUIStore } from "../state/ui-store"

const observatories: { id: Observatory; label: string }[] = [
  { id: "graph", label: "Graph" },
  { id: "authority", label: "Authority" },
  { id: "lineage", label: "Lineage" },
  { id: "dependency", label: "Dependency" },
  { id: "relationship", label: "Relations" },
  { id: "timeline", label: "Timeline" },
  { id: "repository", label: "Repository" },
  { id: "memory", label: "Memory" },
  { id: "ontology", label: "Ontology" },
  { id: "fields", label: "Fields" }
]

type Action = {
  id: string
  label: string
  hint?: string
  run: () => void
  group: string
}

export default function CommandCenter() {
  const {
    commandOpen,
    setCommandOpen,
    setActive
  } = useWorkspaceStore()
  const { mode, setMode, density, setDensity, toggleActivity } = useUIStore()
  const [query, setQuery] = useState("")

  const actions = useMemo<Action[]>(() => {
    const nav: Action[] = observatories.map((o) => ({ id: `nav:${o.id}`, label: `Go to ${o.label}`, run: () => setActive(o.id), group: "Navigate" }))
    const layout: Action[] = [
      { id: "layout:toggle-activity", label: "Toggle activity drawer", run: toggleActivity, group: "Layout" },
      { id: "layout:toggle-dev", label: "Toggle development mode", run: () => setMode(mode === "development" ? "default" : "development"), group: "Layout" },
      { id: "layout:toggle-density", label: `Density: ${density === "compact" ? "comfortable" : "compact"}`, run: () => setDensity(density === "compact" ? "comfortable" : "compact"), group: "Layout" }
    ]
    const focus: Action[] = [
      { id: "focus:composer", label: "Focus composer", run: () => document.querySelector<HTMLTextAreaElement>(".composer textarea")?.focus(), group: "Actions" }
    ]
    return [...nav, ...layout, ...focus]
  }, [setActive, toggleActivity, mode, setMode, density, setDensity])

  useEffect(() => {
    if (!commandOpen) setQuery("")
  }, [commandOpen])

  if (!commandOpen) return null

  return (
    <div
      className="command-backdrop"
      onClick={() => setCommandOpen(false)}
    >
      <Command
        className="command-center"
        onClick={(event) => event.stopPropagation()}
        filter={(value, search) => (value.toLowerCase().includes(search.toLowerCase()) ? 1 : 0)}
        shouldFilter={true}
      >
        <Command.Input placeholder="Type a command…" value={query} onValueChange={setQuery} />
        <Command.Empty>No commands.</Command.Empty>
        <Command.List>
          {Array.from(new Set(actions.map((a) => a.group))).map((group) => (
            <Command.Group key={group} heading={group}>
              {actions.filter((a) => a.group === group).map((action) => (
                <Command.Item
                  key={action.id}
                  onSelect={() => {
                    action.run()
                    setCommandOpen(false)
                  }}
                >
                  {action.label}
                </Command.Item>
              ))}
            </Command.Group>
          ))}
        </Command.List>
      </Command>
    </div>
  )
}


